CREATE TABLE IF NOT EXISTS settlement_rejections (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), team_id BIGINT NOT NULL REFERENCES teams(id), broker_id BIGINT NOT NULL REFERENCES brokers(id), available_cash NUMERIC(16,2) NOT NULL, required_cash NUMERIC(16,2) NOT NULL, shortfall NUMERIC(16,2) NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT now())